-- MAJ63 B : après 63a. Réexécutable.
begin;
alter table public.workshop_lunch_handoffs add column if not exists assigned_staff text references public.workshop_staff(id);
create or replace function public.workshop_lunch_candidates(p_date date) returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();perform workshop_private.assert_section('lunch');return (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'slots',d.slots) order by s.name),'[]') from public.workshop_staff s join public.workshop_days d on d.staff_id=s.id and d.date=p_date where s.active and s.role<>'guest' and s.id is distinct from a->>'self' and exists(select 1 from auth.users u where lower(u.email)=s.email) and d.presence='present' and exists(select 1 from jsonb_array_elements(d.slots)x where p_date>(now() at time zone 'Europe/Paris')::date or (p_date=(now() at time zone 'Europe/Paris')::date and (x->>'end')::time>(now() at time zone 'Europe/Paris')::time)));end $$;
create or replace function public.workshop_lunch_save_v63(p_id uuid,p_date date,p_bt text,p_remaining text,p_version integer,p_assigned text) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;r public.workshop_lunch_handoffs%rowtype;recipient uuid;begin a:=workshop_private.actor();perform workshop_private.assert_section('lunch');perform pg_advisory_xact_lock(hashtextextended('lunch-handoff:'||p_id::text,0));select * into r from public.workshop_lunch_handoffs where id=p_id for update;
if r.id is not null and r.user_id<>auth.uid() and not (a->>'manager')::boolean then raise exception 'Reprise inaccessible.' using errcode='42501';end if;
if r.id is not null and r.date is distinct from p_date then raise exception 'La date de la reprise ne peut pas être modifiée.';end if;
if coalesce(r.version,0) is distinct from p_version then raise exception 'Reprise modifiée ailleurs. Actualise.';end if;
if p_assigned is not null and (r.id is null or r.assigned_staff is distinct from p_assigned) then
perform 1 from public.workshop_days where staff_id=p_assigned and date=p_date for share;
if not exists(select 1 from jsonb_array_elements(public.workshop_lunch_candidates(p_date))x where x->>'id'=p_assigned) then raise exception 'Ce collaborateur n’est plus disponible selon ses horaires.';end if;end if;
if r.id is not null and (a->>'manager')::boolean then perform public.workshop_lunch_manage(p_id,p_version,'edit',p_bt,p_remaining);else perform public.workshop_lunch_save(p_id,p_date,p_bt,p_remaining,p_version);end if;
update public.workshop_lunch_handoffs set assigned_staff=p_assigned where id=p_id;
if p_assigned is not null and (r.id is null or r.assigned_staff is distinct from p_assigned) then select u.id into recipient from auth.users u join public.workshop_staff s on lower(u.email)=s.email where s.id=p_assigned;perform workshop_private.message(recipient,'BT à reprendre : '||trim(p_bt),'/?notifications=lunch&date='||p_date::text,'handoff-assigned:'||p_id::text||':'||(p_version+1));end if;end $$;
create or replace function public.workshop_lunch_list(p_date date) returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();perform workshop_private.assert_section('lunch');return(select coalesce(jsonb_agg(to_jsonb(h)-'user_id'-'taken_by'||jsonb_build_object('author_name',s.name,'assigned_name',t.name,'own',h.user_id=auth.uid(),'can_take',coalesce((a->>'manager')::boolean,false) or h.assigned_staff=a->>'self') order by h.created_at desc),'[]') from public.workshop_lunch_handoffs h join public.workshop_staff s on s.id=h.staff_id left join public.workshop_staff t on t.id=h.assigned_staff where h.date=p_date and (h.user_id=auth.uid() or h.assigned_staff=a->>'self' or coalesce((a->>'manager')::boolean,false)));end $$;
create or replace function public.workshop_lunch_take(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();perform workshop_private.assert_section('lunch');update public.workshop_lunch_handoffs set taken_at=now(),taken_by=auth.uid(),taken_name=(select name from public.workshop_staff where id=a->>'self'),version=version+1,updated_at=now() where id=p_id and version=p_version and taken_at is null and (coalesce((a->>'manager')::boolean,false) or assigned_staff=a->>'self');if not found then raise exception 'Reprise inaccessible, modifiée ou déjà prise en compte.';end if;end $$;
do $$begin if to_regprocedure('workshop_private.lunch_team_before63(timestamptz)') is null then alter function workshop_private.lunch_team(timestamptz) rename to lunch_team_before63;end if;end $$;
create or replace function workshop_private.lunch_team(p_now timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;r jsonb;begin a:=workshop_private.actor();r:=workshop_private.lunch_team_before63(p_now);return(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(r)x join public.workshop_lunch_handoffs h on h.id=(x->>'id')::uuid where h.assigned_staff is null or h.assigned_staff=a->>'self' or (a->>'manager')::boolean);end $$;
revoke all on function workshop_private.lunch_team_before63(timestamptz),workshop_private.lunch_team(timestamptz),public.workshop_lunch_candidates(date),public.workshop_lunch_save_v63(uuid,date,text,text,integer,text),public.workshop_lunch_list(date),public.workshop_lunch_take(uuid,integer) from public,anon,authenticated;
grant execute on function public.workshop_lunch_candidates(date),public.workshop_lunch_save_v63(uuid,date,text,text,integer,text),public.workshop_lunch_list(date),public.workshop_lunch_take(uuid,integer) to authenticated;
notify pgrst,'reload schema';commit;
